import AWSS3

func downloadAllReceipts(bucket: String) async {
    let list = try? await S3Client(region: "ap-south-1").listObjectsV2(input: ListObjectsV2Input(bucket: bucket))
    await withTaskGroup(of: Data?.self) { group in
        for obj in list?.contents ?? [] {
            group.addTask {
                let client = try? await S3Client(region: "ap-south-1")
                let res = try? await client?.getObject(input: GetObjectInput(bucket: bucket, key: obj.key))
                return try? await res?.body?.readData()
            }
        }
    }
}
